{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.izf_sku_style_summary_fact_items as select s.sku_style style, s.sku_size size, date_trunc(date(order_date), week(monday)) as order_week, sum(ifnull(Selling_price,0)) total_sales, count(distinct order_id) total_orders, sum(ifnull(quantity,0)) total_quantity, count(distinct order_id) total_orders, avg(ifnull(rto_returns,0)) rto_returns, avg(ifnull(customer_returns,0)) customer_returns, avg(ifnull(i.Available_Inventory,0)) Available_Inventory, avg(ifnull(sa.ctr,0)) CTR, avg(ifnull(sa.clicks,0)) Clicks, avg(ifnull(sa.total_impressions,0)) Impressions, avg(ifnull(sa.total_add_to_carts,0)) total_add_to_carts, avg(ifnull(sa.Conversion_Rate,0)) Conversion_Rate, avg(ifnull(sa.Return_percent,0)) Return_percent from maplemonk.izf_sales_consolidated s left join ( select sku_style, SKU_SIZE, date_trunc(date(order_date), week(monday)) as order_week, SUM(case when lower(return_type) like \'%rto%\' then IFNULL(TOTAL_RETURNED_QUANTITY, 0) end) as rto_returns, SUM(case when lower(return_type) like \'%return%\' then IFNULL(TOTAL_RETURNED_QUANTITY, 0) end) as customer_returns from maplemonk.izf_returns_consolidated where lower(marketplace) like \'%myntra%\' and not(lower(oms_order_status) like \'%cancel%\' or lower(order_status) like \'%cancel%\') group by 1,2,3 ) r on lower(s.sku_style) = lower(r.sku_style) and lower(s.sku_size) = lower(r.sku_size) and r.order_week = date_trunc(date(s.order_date), week(monday)) left join ( select sku_style, sku_size, date_trunc(date(data_fetch_date), week(monday)) as data_fetch_week, round(avg(ifnull(Available_Inventory,0))) Available_Inventory from maplemonk.izf_inventory_fact_items group by 1,2,3 ) i on lower(s.sku_style) = lower(i.sku_style) and lower(s.sku_size) = lower(i.sku_size) and i.data_fetch_week = date_trunc(date(s.order_date), week(monday)) left join (select Brand, date_trunc(date(week), week(monday)) as order_week, cast(ctr__ as float64)/100 as ctr, Gender, cast(avg_RPLC as float64)/100 as avg_RPLC, cast(ATC_rate__ as float64)/100 as ATC_rate, sa.Article_Type, SPLIT(mm.Article_no, \'-\')[OFFSET(0)] as Style, cast(total_clicks as int64) Clicks, cast(avg_Seller_MRP as int64) avg_Seller_MRP, cast(total_purchases as int64) total_purchases, cast(Conversion_rate__ as float64)/100 as Conversion_Rate, cast(total_impressions as int64) total_impressions, cast(total_add_to_carts as int64) total_add_to_carts, cast(Return___weighted as float64)/100 as Return_percent from maplemonk.gs_myntra_search_analytics sa left join maplemonk.gs_myntra_sku_mapping mm on replace(mm.style_id,\' \',\'\') = cast(sa.style_id as string) ) sa on lower(s.sku_style) = lower(sa.style) and sa.order_week = date_trunc(date(s.order_date), week(monday)) where lower(marketplace) like \'%myntra%\' and not(lower(oms_order_status) like \'%cancel%\' or lower(order_status) like \'%cancel%\') group by 1,2,3;",
                    "transaction": true
